            }
            positions[num]!!.add(Pair(i, j))
        }
    }

    val target = Array(n) { IntArray(m) }
    for (i in 0 until n) {
        for (j in 0 until m) {
            target[i][j] = grid[i][j]
        }
    }

    val dirs = arrayOf(Pair(0, 1), Pair(1, 0), Pair(0, -1), Pair(-1, 0))

    val visited = HashMap<String, Int>()
    val queue = PriorityQueue<State>(compareBy { it.moves })
    queue.add(State(grid, 0))
    visited[gridToString(grid)] = 0

    var answer = Int.MAX_VALUE

    while (queue.isNotEmpty()) {
        val current = queue.poll()
        val currentGrid = current.grid
        val currentMoves = current.moves

        if (isNeat(currentGrid)) {
            answer = currentMoves
            break
        }

        if (currentMoves >= answer) continue

        for (i in 0 until n) {
            for (j in 0 until m) {
                for (dir in dirs) {
                    val ni = i + dir.first
                    val nj = j + dir.second
                    if (ni in 0 until n && nj in 0 until m) {
                        val newGrid = currentGrid.map { it.clone() }.toTypedArray()
                        val temp = newGrid[i][j]
                        newGrid[i][j] = newGrid[ni][nj]
                        newGrid[ni][nj] = temp
                        val key = gridToString(newGrid)
                        val newMoves = currentMoves + 1
                        if (!visited.containsKey(key) || visited[key]!! > newMoves) {
                            visited[key] = newMoves
                            queue.add(State(newGrid, newMoves))
                        }
                    }
                }
            }
        }
    }

    println(answer)
}

fun isNeat(grid: Array<IntArray>): Boolean {
    val n = grid.size
    val m = grid[0].size
    val visited = Array(n) { BooleanArray(m) }
    for (i in 0 until n) {
        for (j in 0 until m) {
            if (!visited[i][j]) {
                val num = grid[i][j]
                var found = false
                for (dir in arrayOf(Pair(0, 1), Pair(1, 0))) {
                    val ni = i + dir.first
                    val nj = j + dir.second
                    if (ni in 0 until n && nj in 0 until m && grid[ni][nj] == num) {
                        if (!visited[ni][nj]) {
                            visited[i][j] = true
                            visited[ni][nj] = true
                            found = true
                            break
                        }
                    }
                }
                if (!found) return false
            }
        }
    }
    return true
}

fun gridToString(grid: Array<IntArray>): String {
    val sb = StringBuilder()
    for (row in grid) {
        sb.append(row.joinToString(","))
        sb.append(";")
    }
    return sb.toString()
}
