### Approach
1. **Problem Analysis**: The problem requires rearranging shoes such that each pair of shoes is adjacent. The challenge is to find the minimum number of moves required to achieve this configuration.
2. **Key Insight**: Each move involves swapping two shoes. The goal is to minimize the number of such swaps. By modeling the problem as a state space where each state represents a configuration of shoes, we can use BFS to explore all possible states efficiently.
3. **State Representation**: Each state is represented by the positions of all shoes. However, due to the potentially large state space, we need an efficient way to track visited states and transitions.
4. **BFS Implementation**: Starting from the initial configuration, we explore all possible moves (swaps) that bring a pair of shoes closer to being adjacent. The BFS ensures that we find the shortest path (minimum moves) to a valid configuration.

### Solution Code
```kotlin
import java.util.*

data class State(val positions: Array<IntArray>, val moves: Int)

fun main() {
    val (n, m) = readLine()!!.split(" ").map { it.toInt() }
    val grid = Array(n) { IntArray(m) }
    val shoePositions = mutableMapOf<Int, MutableList<Pair<Int, Int>>>()

    for (i in 0 until n) {
        val row = readLine()!!.split(" ").map { it.toInt() }.toIntArray()
        grid[i] = row
        for (j in 0 until m) {
            val num = row[j]
            shoePositions.getOrPut(num) { mutableListOf() }.add(Pair(i, j))
        }
    }

    val pairs = shoePositions.values.toList()
    val visited = mutableSetOf<String>()
    val queue = LinkedList<State>()

    fun serialize(state: Array<IntArray>): String {
        return state.joinToString("") { it.joinToString(",") }
    }

    val initial = Array(n) { IntArray(m) }
    for (i in 0 until n) {
        initial[i] = grid[i].clone()
    }
    queue.add(State(initial, 0))
    visited.add(serialize(initial))

    var result = Int.MAX_VALUE

    while (queue.isNotEmpty()) {
        val current = queue.poll()
        val currentGrid = current.positions
        val currentMoves = current.moves

        if (currentMoves >= result) continue

        var allPaired = true
        for (pair in pairs) {
            val (i1, j1) = pair[0]
            val (i2, j2) = pair[1]
            if (Math.abs(i1 - i2) + Math.abs(j1 - j2) != 1) {
                allPaired = false
                break
            }
        }
        if (allPaired) {
            result = minOf(result, currentMoves)
            continue
        }

        for (i in 0 until n) {
            for (j in 0 until m) {
                val num = currentGrid[i][j]
                val otherPos = if (shoePositions[num]!![0] == Pair(i, j)) shoePositions[num]!![1] else shoePositions[num]!![0]
                val (oi, oj) = otherPos
                if (Math.abs(i - oi) + Math.abs(j - oj) == 1) continue

                for (dx in -1..1) {
                    for (dy in -1..1) {
                        if (dx == 0 && dy == 0) continue
                        val ni = i + dx
                        val nj = j + dy
                        if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue
                        val targetNum = currentGrid[ni][nj]
                        val targetOther = if (shoePositions[targetNum]!![0] == Pair(ni, nj)) shoePositions[targetNum]!![1] else shoePositions[targetNum]!![0]
                        val (ti, tj) = targetOther
                        if (Math.abs(ni - ti) + Math.abs(nj - tj) == 1) continue

                        val newGrid = Array(n) { IntArray(m) }
                        for (a in 0 until n) {
                            newGrid[a] = currentGrid[a].clone()
                        }
                        newGrid[i][j] = targetNum
                        newGrid[ni][nj] = num

                        val key = serialize(newGrid)
                        if (!visited.contains(key)) {
                            visited.add(key)
                            queue.add(State(newGrid, currentMoves + 1))
                        }
                    }
                }
            }
        }
    }

    println(result)
}
